        const App = () => {
            useEffect(() => { lucide.createIcons(); }, []);
            return (
                <div className="pt-20">
                    <Hero />
                    <Marquee />
                    <TestimonialQuote />
                    <Pricing />
                    <TestimonialCarousel />
                    <Projects />
                    <PartnerCTA />
                    <Footer />
                    <FixedNav />
                </div>
            );
        };

export default App;

