const App = () => {
            useEffect(() => { lucide.createIcons(); }, []);
            const brands = ['GUCCI', 'ZARA', 'VOGUE', 'SONY', 'ZALORA'];
            return (
                <div className="relative min-h-screen overflow-hidden" style={{ background: 'linear-gradient(180deg, #fd2601 0%, #f37e1c 100%)' }}>
                    {/* Background Name */}
                    <div className="absolute inset-0 flex items-center justify-center pointer-events-none z-0">
                        <span className="text-white/[0.08] text-[20vw] font-bold uppercase" style={{ fontFamily: "'Anton',sans-serif", filter: 'blur(4px)' }}>OLIVIA</span>
                    </div>
                    {/* Glowing blobs */}
                    <div className="absolute bottom-[-5%] right-[10%] w-[300px] h-[300px] rounded-full opacity-60 mix-blend-screen pointer-events-none" style={{ background: '#F4791B', filter: 'blur(80px)' }}></div>
                    <div className="absolute bottom-[-5%] left-[5%] w-[600px] h-[300px] rounded-full opacity-60 mix-blend-screen pointer-events-none" style={{ background: '#F4791B', filter: 'blur(80px)' }}></div>

                    {/* Navbar */}
                    <nav className="absolute top-0 left-0 right-0 z-30 flex items-center justify-between px-6 md:px-12 py-6">
                        <span className="text-white text-sm font-medium tracking-widest uppercase" style={{ fontFamily: "'Inter',sans-serif" }}>✱ VIKTORODDY</span>
                        <div className="hidden md:flex items-center gap-8">
                            {['PROJECTS','BLOG','ABOUT','RESUME'].map(l => (
                                <a key={l} href="#" className="text-white text-xs tracking-widest uppercase hover:opacity-80 transition-opacity">{l}</a>
                            ))}
                        </div>
                        <div className="flex items-center gap-3">
                            <span className="text-white text-xs tracking-widest uppercase hidden sm:inline">// HIRE ME</span>
                            <button className="w-10 h-10 rounded-full border-2 border-white flex items-center justify-center group hover:bg-white transition-colors">
                                <i data-lucide="arrow-up-right" className="w-4 h-4 text-white group-hover:text-[#fd2601] transition-colors"></i>
                            </button>
                        </div>
                    </nav>

                    {/* Hero Content */}
                    <div className="relative z-10 min-h-screen flex flex-col items-center justify-center px-6 pt-24 pb-32">
