                        </div>
                        <div className="hidden lg:block absolute right-12 top-1/2 -translate-y-1/2 z-30 text-white text-sm text-right leading-relaxed">
                            <span className="opacity-60">// </span>DESIGN THAT<br />SPEAKS YOUR BRAND
                        </div>
                        {/* Mobile floating text */}
